import * as React from "react";
import { cx } from "./cx";

export interface Crumb {
  label: React.ReactNode;
  href?: string;
}

export interface BreadcrumbsProps extends React.HTMLAttributes<HTMLElement> {
  items: Crumb[];
}

export function Breadcrumbs({ items, className, ...props }: BreadcrumbsProps) {
  return (
    <nav aria-label="Breadcrumbs" className={cx("rs-crumbs", className)} {...props}>
      {items.map((item, index) => {
        const last = index === items.length - 1;
        return (
          <React.Fragment key={index}>
            {index > 0 && (
              <span className="rs-crumbs-sep" aria-hidden="true">
                /
              </span>
            )}
            {last ? (
              <span className="rs-crumbs-here" aria-current="page">
                {item.label}
              </span>
            ) : item.href ? (
              <a href={item.href}>{item.label}</a>
            ) : (
              <span>{item.label}</span>
            )}
          </React.Fragment>
        );
      })}
    </nav>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Breadcrumbs — slashes at 40%, current page is ink ── */
.rs-crumbs{font-size:13px;color:var(--text-secondary);letter-spacing:-.01em;display:flex;gap:8px}
.rs-crumbs-sep{opacity:.4}
.rs-crumbs-here{color:var(--text)}
